 * Parse the build-graph text into a task cost map and a dependency
 * adjacency map (task name -> Set of names it depends on).
 */
export function parseGraph(input) {
  const lines = splitLines(input)
  const tasks = new Map()
  const adjacency = new Map()
  const usageOrder = []

  function ensureSet(name) {
    if (!adjacency.has(name)) adjacency.set(name, new Set())
    return adjacency.get(name)
  }

  for (let i = 0; i < lines.length; i += 1) {
    const lineNumber = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNumber}: expected task <name> <cost>`, 2)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNumber}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNumber}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNumber}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, parseInt(costStr, 10))
      ensureSet(name)
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNumber}: expected dep <name> <dependency>...`, 2)
      }
      const name = words[1]
      const deps = words.slice(2)
      for (const nm of [name, ...deps]) {
