 * Graph analysis helpers shared by the waves/explain/pack modes: cycle
 * detection, wave depth, unlimited-worker timing, and pack priority.
 */

function depsOf(adjacency, name) {
  return adjacency.get(name) || new Set()
}

/**
 * Depth-first search for the first cycle, starting from each task in
 * ascending name order and walking dependencies in ascending name order.
 * Returns an array of names forming the cycle (first name repeated at the
 * end), or null when the graph is acyclic.
 */
export function findCycle(tasks, adjacency) {
  const names = [...tasks.keys()].sort()
  const state = new Map(names.map((n) => [n, 0])) // 0 unvisited, 1 visiting, 2 done
  const stack = []

  function visit(node) {
    state.set(node, 1)
    stack.push(node)
    const children = [...depsOf(adjacency, node)].sort()
    for (const child of children) {
      const childState = state.get(child)
      if (childState === 1) {
        const idx = stack.indexOf(child)
        return stack.slice(idx).concat(child)
      }
      if (childState === 0) {
        const found = visit(child)
        if (found) return found
      }
    }
    stack.pop()
    state.set(node, 2)
    return null
  }

  for (const start of names) {
    if (state.get(start) === 0) {
      const found = visit(start)
      if (found) return found
    }
  }
  return null
}

/**
 * depth(t) = 0 when t has no dependency, else 1 + max depth of its
 * dependencies. Assumes the graph is acyclic.
 */
export function computeDepths(tasks, adjacency) {
  const memo = new Map()
  function depth(name) {
    if (memo.has(name)) return memo.get(name)
    const deps = [...depsOf(adjacency, name)]
    const value = deps.length === 0 ? 0 : 1 + Math.max(...deps.map(depth))
    memo.set(name, value)
    return value
  }
  return depth
}

/**
 * Unlimited-worker start/finish times: start is the greatest finish among
 * dependencies (0 when none), finish is start + cost.
 */
export function computeTimes(tasks, adjacency) {
  const startMemo = new Map()
  const finishMemo = new Map()

  function finish(name) {
    if (finishMemo.has(name)) return finishMemo.get(name)
    const value = start(name) + tasks.get(name)
    finishMemo.set(name, value)
    return value
  }

  function start(name) {
    if (startMemo.has(name)) return startMemo.get(name)
    const deps = [...depsOf(adjacency, name)]
    const value = deps.length === 0 ? 0 : Math.max(...deps.map(finish))
    startMemo.set(name, value)
    return value
  }

  return { start, finish }
}

/**
 * Reverse adjacency: for each task, the set of tasks that depend on it.
 */
export function computeDependents(tasks, adjacency) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of adjacency) {
    for (const dep of deps) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(name)
    }
  }
  return dependents
}

/**
 * priority(t) = cost(t) plus the greatest priority among the tasks that
 * depend on t (0 when nothing depends on it): the cost of the longest
 * chain that begins at t and runs up to a task nothing depends on.
 */
export function computePriorities(tasks, adjacency) {
  const dependents = computeDependents(tasks, adjacency)
  const memo = new Map()
  function priority(name) {
    if (memo.has(name)) return memo.get(name)
    const ups = dependents.get(name) || []
    const value = tasks.get(name) + (ups.length === 0 ? 0 : Math.max(...ups.map(priority)))
    memo.set(name, value)
    return value
  }
  return priority
}
